1	import type { ModelProfile } from './model-profile'
2	
3	/** Token accounting for one assistant turn, as far as the engine reports it. */
4	export type TurnUsage = {
5	  inputTokens: number
6	  outputTokens: number
7	  cacheReadTokens: number
8	  cacheWriteTokens: number
9	  costUsd?: number
10	}
11	
12	/** What an engine is told about one call. Remembering a decision is the host's business, not the engine's. */
13	export type PermissionDecision = { kind: 'allow' } | { kind: 'deny'; message?: string }
14	
15	/**
16	 * What a session emits. One shape for every engine so the UI, the run log and
17	 * later the phase orchestration never see wire formats.
18	 *
19	 * `parentToolUseId` is set on events produced inside a subagent.
20	 */
21	export type SessionEvent =
22	  | { type: 'session_started'; engineSessionId: string; model: string; engineVersion?: string }
23	  | { type: 'user_message'; text: string }
24	  | { type: 'assistant_text'; messageId: string; delta: string; parentToolUseId?: string }
25	  | { type: 'assistant_thinking'; messageId: string; delta: string; parentToolUseId?: string }
26	  /** Final text of an assistant message, replaces whatever was streamed under the same id. */
27	  | { type: 'assistant_message'; messageId: string; text: string; parentToolUseId?: string }
28	  | { type: 'tool_call'; toolUseId: string; name: string; input: unknown; parentToolUseId?: string }
29	  | { type: 'tool_result'; toolUseId: string; text: string; isError: boolean; parentToolUseId?: string }
30	  | {
31	      type: 'permission_request'
32	      requestId: string
33	      toolName: string
34	      input: unknown
35	      title?: string
36	      description?: string
37	    }
38	  | { type: 'permission_resolved'; requestId: string; decision: PermissionDecision['kind'] }
39	  | { type: 'status'; status: 'requesting' | 'compacting' | 'verifying' | 'idle' }
40	  | { type: 'verification_started'; command: string; cwd: string }
41	  | { type: 'verification'; command: string; cwd: string; ok: boolean; output: string }
42	  | { type: 'turn_done'; usage?: TurnUsage; durationMs?: number; isError: boolean; errors: string[] }
43	  | { type: 'error'; message: string; fatal: boolean }
44	  | { type: 'ended' }
45	
46	export type SessionEventType = SessionEvent['type']
47	
48	/**
49	 * A coding session on one engine. Session-centric on purpose: the extension
50	 * sends prompts and reacts to events; how the engine talks to its model is
51	 * the engine's business.
52	 */
53	export interface CodeSession {
54	  readonly id: string
55	  readonly profile: ModelProfile
56	  /** Queue a user turn. Returns immediately. */
57	  send(text: string): void
58	  /** Single consumer. Ends after the `ended` event. */
59	  events(): AsyncIterable<SessionEvent>
60	  respondToPermission(requestId: string, decision: PermissionDecision): void
61	  /** Stop the current turn; the session stays usable. */
62	  interrupt(): Promise<void>
63	  /** Terminate the engine and release resources. */
64	  dispose(): Promise<void>
65	}
