17	type QueryFn = (params: { prompt: AsyncIterable<SDKUserMessage>; options?: Options }) => Query
18	
19	export type SdkSessionOptions = {
20	  id: string
21	  profile: ModelProfile
22	  cwd: string
23	  /** Absolute path to the SDK's cli.js. */
24	  cliPath: string
25	  runtime: NodeRuntime
26	  /** Engine session id from an earlier `session_started`, to continue that conversation. */
27	  resumeEngineSessionId?: string
28	  /** Extra environment for the engine process, on top of the host's. */
29	  env?: Record<string, string>
30	  hooks?: SessionHooks
31	  /** Replaces Claude Code's own system prompt; phases use this. */
32	  systemPrompt?: string
33	  /** Restricts the built-in tools to these names. */
34	  tools?: string[]
35	  query: QueryFn
