46	/**
47	 * Claude through the Agent SDK. One `query()` in streaming-input mode per
48	 * session, so one engine process serves every turn of the conversation.
49	 */
50	export class SdkSession implements CodeSession {
51	  readonly id: string
52	  readonly profile: ModelProfile
53	  private readonly input = new AsyncQueue<SDKUserMessage>()
54	  private readonly output = new AsyncQueue<SessionEvent>()
55	  private readonly pending = new Map<string, PendingPermission>()
56	  private readonly mapper = new SdkEventMapper()
57	  private readonly abort = new AbortController()
58	  private readonly query: Query
59	  private readonly pumping: Promise<void>
60	  private engineSessionId: string | undefined
61	
62	  constructor(private readonly options: SdkSessionOptions) {
63	    this.id = options.id
64	    this.profile = options.profile
65	    this.engineSessionId = options.resumeEngineSessionId
66	    this.query = options.query({ prompt: this.input, options: this.buildOptions() })
67	    this.pumping = this.pump()
68	  }
69	
70	  /** Engine-side id, known after `session_started`. Needed to resume after a reload. */
71	  get engineSession(): string | undefined {
72	    return this.engineSessionId
73	  }
74	
75	  send(text: string): void {
76	    this.output.push({ type: 'user_message', text })
77	    this.input.push({
78	      type: 'user',
79	      message: { role: 'user', content: text },
80	      parent_tool_use_id: null,
81	    })
82	  }
83	
84	  events(): AsyncIterable<SessionEvent> {
85	    return this.output
86	  }
87	
88	  respondToPermission(requestId: string, decision: PermissionDecision): void {
89	    const pending = this.pending.get(requestId)
90	    if (!pending) return
91	    this.pending.delete(requestId)
92	    this.output.push({ type: 'permission_resolved', requestId, decision: decision.kind })
93	    pending.resolve(toPermissionResult(decision, pending.input))
94	  }
95	
96	  async interrupt(): Promise<void> {
97	    await this.query.interrupt()
98	  }
99	
100	  async dispose(): Promise<void> {
101	    this.denyAllPending('Session closed')
102	    this.input.end()
103	    this.abort.abort()
104	    this.query.close()
105	    // The engine stream normally completes once the process is gone; the
106	    // timeout covers a process that will not die.
107	    await Promise.race([this.pumping, new Promise((r) => setTimeout(r, 2000))])
108	    this.finish()
109	  }
110	
111	  private buildOptions(): Options {
112	    const { profile } = this.options
113	    const options: Options = {
114	      abortController: this.abort,
115	      cwd: this.options.cwd,
116	      model: profile.model,
117	      permissionMode: 'default',
118	      includePartialMessages: true,
119	      // Project settings so the workspace's .claude/ and CLAUDE.md apply; not
120	      // the user's global settings, which belong to this machine, not the repo.
121	      settingSources: ['project', 'local'],
122	      executable: 'node',
123	      pathToClaudeCodeExecutable: this.options.cliPath,
124	      spawnClaudeCodeProcess: spawnWithRuntime(this.options.runtime, this.options.onStderr ?? (() => {})),
125	      canUseTool: (toolName, input, ctx) => this.requestPermission(toolName, input, ctx),
126	      env: this.options.env ?? {},
127	    }
128	    if (profile.effort) options.effort = profile.effort
129	    if (this.options.resumeEngineSessionId) options.resume = this.options.resumeEngineSessionId
130	    if (this.options.hooks) options.hooks = this.sdkHooks(this.options.hooks)
131	    if (this.options.systemPrompt !== undefined) options.systemPrompt = this.options.systemPrompt
132	    if (this.options.tools) options.tools = this.options.tools
133	    return options
134	  }
135	
136	  /** Maps the engine-agnostic hooks onto the SDK's hook protocol. */
137	  private sdkHooks(hooks: SessionHooks): NonNullable<Options['hooks']> {
138	    const registered: NonNullable<Options['hooks']> = {}
139	    if (hooks.preToolUse) {
140	      const pre = hooks.preToolUse.bind(hooks)
141	      const callback: HookCallback = async (input): Promise<HookJSONOutput> => {
142	        if (input.hook_event_name !== 'PreToolUse') return {}
143	        const outcome = await pre({ toolName: input.tool_name, input: input.tool_input, toolUseId: input.tool_use_id })
144	        if (outcome && 'deny' in outcome) {
145	          return { hookSpecificOutput: { hookEventName: 'PreToolUse', permissionDecision: 'deny', permissionDecisionReason: outcome.deny } }
146	        }
147	        if (!outcome?.allow && !outcome?.additionalContext) return {}
148	        return {
149	          hookSpecificOutput: {
150	            hookEventName: 'PreToolUse',
151	            ...(outcome.allow ? { permissionDecision: 'allow' } : {}),
152	            ...(outcome.additionalContext ? { additionalContext: outcome.additionalContext } : {}),
153	          },
154	        }
155	      }
156	      registered.PreToolUse = [{ hooks: [callback] }]
157	    }
158	    if (hooks.postToolUse) {
159	      const post = hooks.postToolUse.bind(hooks)
160	      const callback: HookCallback = async (input): Promise<HookJSONOutput> => {
161	        if (input.hook_event_name !== 'PostToolUse') return {}
162	        const output = typeof input.tool_response === 'string' ? input.tool_response : JSON.stringify(input.tool_response)
163	        const outcome = await post({
164	          toolName: input.tool_name,
165	          input: input.tool_input,
166	          toolUseId: input.tool_use_id,
167	          output,
168	          isError: false,
169	        })
170	        if (outcome?.additionalContext) {
171	          return { hookSpecificOutput: { hookEventName: 'PostToolUse', additionalContext: outcome.additionalContext } }
172	        }
173	        return {}
174	      }
175	      registered.PostToolUse = [{ hooks: [callback] }]
176	    }
177	    if (hooks.stop) {
178	      const stop = hooks.stop.bind(hooks)
179	      const callback: HookCallback = async (input): Promise<HookJSONOutput> => {
180	        if (input.hook_event_name !== 'Stop') return {}
181	        this.output.push({ type: 'status', status: 'verifying' })
182	        const outcome = await stop((started) => this.output.push({ type: 'verification_started', ...started }))
183	        for (const v of outcome?.verifications ?? []) this.output.push({ type: 'verification', ...v })
184	        return outcome?.block ? { decision: 'block', reason: outcome.block } : {}
185	      }
186	      // Builds can take a while; the SDK's default hook timeout would cut them off.
187	      registered.Stop = [{ hooks: [callback], timeout: 900 }]
188	    }
189	    return registered
190	  }
191	
192	  private requestPermission(
193	    toolName: string,
194	    input: Record<string, unknown>,
195	    ctx: Parameters<NonNullable<Options['canUseTool']>>[2],
196	  ): Promise<PermissionResult> {
197	    return new Promise((resolve) => {
198	      const requestId = ctx.toolUseID
199	      this.pending.set(requestId, { resolve, input })
200	      ctx.signal.addEventListener('abort', () => {
201	        if (this.pending.delete(requestId)) resolve({ behavior: 'deny', message: 'Cancelled' })
202	      })
203	      this.output.push({
204	        type: 'permission_request',
205	        requestId,
206	        toolName,
207	        input,
208	        ...(ctx.title ? { title: ctx.title } : {}),
209	        ...(ctx.description ? { description: ctx.description } : {}),
210	      })
211	    })
212	  }
213	
214	  private denyAllPending(message: string): void {
215	    for (const [id, pending] of this.pending) {
216	      this.pending.delete(id)
217	      pending.resolve({ behavior: 'deny', message })
218	    }
219	  }
220	
221	  private async pump(): Promise<void> {
222	    try {
223	      for await (const message of this.query) {
224	        this.options.trace?.(describeMessage(message))
225	        for (const event of this.mapper.map(message)) {
226	          if (event.type === 'session_started') this.engineSessionId = event.engineSessionId
227	          this.output.push(event)
228	        }
229	      }
230	    } catch (error) {
231	      if (!this.abort.signal.aborted) {
232	        this.output.push({ type: 'error', message: errorMessage(error), fatal: true })
233	      }
234	    } finally {
235	      this.denyAllPending('Session ended')
236	      this.finish()
237	    }
238	  }
239	
240	  private finish(): void {
241	    if (this.output.isEnded) return
242	    this.output.push({ type: 'ended' })
243	    this.output.end()
244	  }
245	}
246	
247	/**
248	 * The engine validates an allow as `{ updatedInput: record }`, so the
249	 * unchanged input is echoed back; the typings mark it optional but the
250	 * CLI does not.
251	 */
252	function toPermissionResult(decision: PermissionDecision, input: Record<string, unknown>): PermissionResult {
253	  switch (decision.kind) {
254	    case 'allow':
255	      return { behavior: 'allow', updatedInput: input, decisionClassification: 'user_temporary' }
256	    case 'deny':
257	      return { behavior: 'deny', message: decision.message ?? 'Denied by user', decisionClassification: 'user_reject' }
258	  }
259	}
260	
261	function errorMessage(error: unknown): string {
262	  return error instanceof Error ? error.message : String(error)
263	}
264	
265	/** One line per engine message: kind, and for stream events the raw event and delta kinds. */
266	export function describeMessage(msg: SDKMessage): string {
267	  switch (msg.type) {
268	    case 'stream_event': {
269	      const event = msg.event as { type: string; delta?: { type?: string }; content_block?: { type?: string } }
270	      const detail = event.delta?.type ?? event.content_block?.type
271	      return `stream_event ${event.type}${detail ? ` ${detail}` : ''}`
272	    }
273	    case 'system':
274	      return `system ${msg.subtype}${'status' in msg ? ` ${String(msg.status)}` : ''}`
275	    case 'assistant':
276	      return `assistant [${msg.message.content.map((b) => b.type).join(', ')}]`
277	    case 'user': {
278	      const content = msg.message.content
279	      return `user ${typeof content === 'string' ? 'text' : `[${content.map((b) => b.type).join(', ')}]`}`
280	    }
281	    case 'result':
282	      return `result ${msg.subtype} ${msg.duration_ms}ms`
283	    default:
284	      return msg.type
285	  }
286	}
