1	/**
2	 * Engine-agnostic hook points. The Claude engine maps them onto the SDK's
3	 * PreToolUse / PostToolUse / Stop hooks, the own-loop engine calls them
4	 * directly, so a hook is written once.
5	 */
6	
7	export type ToolUse = { toolName: string; input: unknown; toolUseId: string }
8	
9	/** `allow` skips the permission prompt: the hook has ruled the call safe. */
10	export type PreToolUseOutcome =
11	  | { deny: string }
12	  | { allow?: true; additionalContext?: string }
13	  | undefined
14	
15	export type PostToolUseOutcome = { additionalContext?: string } | undefined
16	
17	export type VerificationResult = { command: string; cwd: string; ok: boolean; output: string }
18	
19	/** `block` sends the reason back to the model and the turn continues. */
20	export type StopOutcome = { verifications?: VerificationResult[]; block?: string } | undefined
21	
22	export type VerificationStarted = { command: string; cwd: string }
23	
24	export interface SessionHooks {
25	  preToolUse?(tool: ToolUse): Promise<PreToolUseOutcome>
26	  postToolUse?(tool: ToolUse & { output: string; isError: boolean }): Promise<PostToolUseOutcome>
27	  /** The model wants to end its turn. `onStarted` fires before each verification command so the UI can show progress. */
28	  stop?(onStarted: (started: VerificationStarted) => void): Promise<StopOutcome>
29	}
30	
31	/** Runs several hooks in order: the first deny or block wins, any allow allows, contexts are joined. */
32	export function composeHooks(...hooks: SessionHooks[]): SessionHooks {
33	  return {
34	    async preToolUse(tool) {
35	      const contexts: string[] = []
36	      let allow = false
37	      for (const hook of hooks) {
38	        const outcome = await hook.preToolUse?.(tool)
39	        if (outcome && 'deny' in outcome) return outcome
40	        if (outcome?.allow) allow = true
41	        if (outcome?.additionalContext) contexts.push(outcome.additionalContext)
42	      }
43	      if (!allow && contexts.length === 0) return undefined
44	      return { ...(allow ? { allow: true as const } : {}), ...(contexts.length ? { additionalContext: contexts.join('\n\n') } : {}) }
45	    },
46	    async postToolUse(tool) {
47	      const contexts: string[] = []
48	      for (const hook of hooks) {
49	        const outcome = await hook.postToolUse?.(tool)
50	        if (outcome?.additionalContext) contexts.push(outcome.additionalContext)
51	      }
52	      return contexts.length ? { additionalContext: contexts.join('\n\n') } : undefined
53	    },
54	    async stop(onStarted) {
55	      const verifications: VerificationResult[] = []
56	      for (const hook of hooks) {
57	        const outcome = await hook.stop?.(onStarted)
58	        verifications.push(...(outcome?.verifications ?? []))
59	        if (outcome?.block) return { verifications, block: outcome.block }
60	      }
61	      return verifications.length ? { verifications } : undefined
62	    },
63	  }
64	}
