1	import { appendFile, mkdir, readFile } from 'node:fs/promises'
2	import { join } from 'node:path'
3	import type { SessionEvent } from '../session/code-session'
4	
5	export type RunLogEntry = { at: string; event: SessionEvent }
6	
7	/**
8	 * Append-only JSONL of every event a session produced, one file per session
9	 * under `.agent/runs/<session id>/events.jsonl`. The transcript view is
10	 * rebuilt from it after a reload, and later phases read it for observability.
11	 *
12	 * Writes are chained so entries land in emission order even when the caller
13	 * does not await.
14	 */
15	export class RunLog {
16	  private chain: Promise<void> = Promise.resolve()
17	
18	  constructor(private readonly dir: string) {}
19	
20	  static forSession(workspaceRoot: string, sessionId: string): RunLog {
21	    return new RunLog(join(workspaceRoot, '.agent', 'runs', sessionId))
22	  }
23	
24	  get path(): string {
25	    return join(this.dir, 'events.jsonl')
26	  }
27	
28	  append(event: SessionEvent): Promise<void> {
29	    const entry: RunLogEntry = { at: new Date().toISOString(), event }
30	    this.chain = this.chain.then(async () => {
31	      await mkdir(this.dir, { recursive: true })
32	      await appendFile(this.path, JSON.stringify(entry) + '\n', 'utf8')
33	    })
34	    return this.chain
35	  }
36	
37	  async read(): Promise<RunLogEntry[]> {
38	    let text: string
39	    try {
40	      text = await readFile(this.path, 'utf8')
41	    } catch (error) {
42	      if (isMissingFile(error)) return []
43	      throw error
44	    }
45	    return text
46	      .split('\n')
47	      .filter((line) => line.length > 0)
48	      .map((line) => JSON.parse(line) as RunLogEntry)
49	  }
50	}
51	
52	function isMissingFile(error: unknown): boolean {
53	  return typeof error === 'object' && error !== null && 'code' in error && error.code === 'ENOENT'
54	}
