254	  private finishTurn(usage: TurnUsage, started: number, isError: boolean, errors: string[]): void {
255	    this.output.push({ type: 'status', status: 'idle' })
256	    this.output.push({ type: 'turn_done', usage, durationMs: Date.now() - started, isError, errors })
