46	  private check(raw: unknown, globs: string[], verb: string, directory = false): PreToolUseOutcome {
47	    if (typeof raw !== 'string') return { deny: `Cannot ${verb}: no path given.` }
48	    const absolute = isAbsolute(raw) ? raw : resolve(this.cwd, raw)
49	    const rel = relative(this.cwd, absolute).split('\\').join('/')
50	    if (rel.startsWith('..')) return { deny: `Cannot ${verb} outside the workspace: ${raw}` }
51	    const ignored = (this.scope.ignored ?? []).find((g) => matchesGlob(rel, g) || (directory && matchesGlob(`${rel}/x`, g)))
52	    if (ignored) return { deny: `Cannot ${verb} ${raw}: excluded from this phase by the ignore setting (${ignored}).` }
53	    // A search directory must itself lie inside the allowed tree: searching
54	    // from the workspace root would list names of files the phase must not see.
55	    const allowed = globs.some((g) => matchesGlob(rel, g) || (directory && matchesGlob(`${rel}/x`, g)))
56	    if (allowed) return undefined
57	    return { deny: `Cannot ${verb} ${raw}: this phase is limited to ${globs.join(', ')}.` }
58	  }
